 const applyRecommendedDates=async()=>{if(!tripDraft?.id)return;const rec=tripDraft?.notes?.optimization?.dateOptimization?.recommended;if(!rec?.date){setStatus('Aucune fenêtre recommandée n’est encore disponible. Lancez d’abord l’analyse.');return}setTripDraftLoading(true);try{const duration=Number(rec.durationDays)||Number(tripDraft?.notes?.dates?.durationDays)||7;const start=new Date(rec.date+'T00:00:00Z');const end=new Date(start);end.setUTCDate(end.getUTCDate()+duration-1);const d=await v30fetch('/api/platform/v30/trip-draft/'+tripDraft.id+'/dates',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({startDate:rec.date,endDate:end.toISOString().slice(0,10),flexibleDays:tripDraft?.notes?.dates?.flexibleDays||0,durationDays:duration})});setTripDraft(d.draft);setStatus('Fenêtre recommandée enregistrée dans votre projet : '+rec.date+' · '+duration+' jour(s).')}catch(e){setStatus('Impossible d’enregistrer cette fenêtre pour le moment.')}finally{setTripDraftLoading(false)}};
 const composeTrip=async()=>{if(!tripDraft?.id)return;setTripDraftLoading(true);try{const d=await v30fetch('/api/platform/v30/trip-draft/'+tripDraft.id+'/compose',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({solutionIds:selectedSolutions.slice(0,3),transport:tripDraft.transport,accommodation:tripDraft.accommodation,healthSafety:tripDraft.health_safety,notes:{...(tripDraft.notes||{}),composedAt:new Date().toISOString()}})});setTripDraft(d.draft);setTripDraftStatus(d.draft.status||'ready');setStatus(d.selectedSolutions?.length?'Votre projet a été composé à partir de vos choix. Vous pouvez encore le modifier.':'Votre projet a été actualisé. Vous gardez la main sur chaque élément.')}catch(e){setStatus('Impossible de composer le projet pour le moment.')}finally{setTripDraftLoading(false)}};
 const updateTripDraftStatus=async status=>{if(!tripDraft?.id)return;setTripDraftLoading(true);try{const d=await v30fetch('/api/platform/v30/trip-draft/'+tripDraft.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});setTripDraft(d.draft);setTripDraftStatus(d.draft.status);setStatus(status==='ready'?'Votre projet est prêt à être relu. Rien n’est réservé automatiquement.':'Votre projet reste ouvert : vous pouvez encore le faire évoluer.')}catch(e){setStatus('Impossible de modifier l’état du projet pour le moment.')}finally{setTripDraftLoading(false)}};
