    <div className="v32Children">{children.map(n=><button key={n.node_key} onClick={()=>open(n)}><span>{n.node_type}</span><b>{n.name}</b><small>{n.hemisphere||'—'} · {(n.climate_keys||[]).join(', ')||'climat non renseigné'}</small></button>)}</div>
